function validate([nums]) {
  const n = nums.length - 2;
  if (n < 2 || n > 100) return 'nums needs 4 to 102 values (n from 2 to 100).';
  if (nums.some(v => v < 0 || v >= n)) return 'Each value is between 0 and n - 1, where n = nums.length - 2.';
  const count = new Array(n).fill(0);
  for (const v of nums) count[v]++;
  if (count.some(c => c === 0) || count.filter(c => c === 2).length !== 2) return 'Every value from 0 to n - 1 appears once, except two values that appear twice.';
  return null;
}

