function getSneakyNumbers(nums) {
  const seen = new Set();
  const sneaky = [];
  for (const num of nums) {
    if (seen.has(num)) {
      sneaky.push(num);
    } else {
      seen.add(num);
    }
  }
  return sneaky;
}

