function getSneakyNumbers(nums) {
  // Count each possible value with a full scan of nums.
  const repeated = [];
  for (let value = 0; value < nums.length; value++) {
    if (nums.filter(x => x === value).length === 2) repeated.push(value);
  }
  return repeated;
}

