function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const first = Math.floor(rand() * n);
  let second = Math.floor(rand() * (n - 1));
  if (second >= first) second++;
  const nums = [...Array(n).keys(), first, second];
  // Sorted, reversed or shuffled, so the repeats can sit side by side or far apart.
  const order = Math.floor(rand() * 4);
  if (order === 0) return [nums.sort((a, b) => a - b)];
  if (order === 1) return [nums.sort((a, b) => b - a)];
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
